/* ============ Visionneuse de fichiers intégrée ============ */
const FILES = {
    readme: {
        name: 'README.md',
        path: 'README.md',
        lang: 'markdown',
        b64: ""
    },
    license: {
        name: 'LICENSE',
        path: 'LICENSE',
        lang: 'text',
        b64: ""
    },
    py: {
        name: 'acc_converter.py',
        path: 'converter/acc_converter.py',
        lang: 'python',
        b64: ""
    },
    js: {
        name: 'acc_converter.js',
        path: 'converter/acc_converter.js',
        lang: 'javascript',
        b64: ""
    },
    test: {
        name: 'test_converter.py',
        path: 'converter/tests/test_converter.py',
        lang: 'python',
        b64: ""
    },
    kbxml: {
        name: 'ht-t-k0-aac.xml',
        path: 'keyboard/ht-t-k0-aac.xml',
        lang: 'xml',
        b64: ""
    },
    kbguide: {
        name: 'keyboard/README.md',
        path: 'keyboard/README.md',
        lang: 'markdown',
        b64: ""
    },
};

function decodeB64Utf8(b64) {
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return new TextDecoder('utf-8').decode(bytes);
}

function escapeHtml(s) {
    return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function highlightPython(code) {
    let out = escapeHtml(code);
    out = out.replace(/(#.*)$/gm, '<span class="tok-com">$1</span>');
    out = out.replace(/("""[\s\S]*?"""|'''[\s\S]*?''')/g, '<span class="tok-str">$1</span>');
    out = out.replace(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/g, '<span class="tok-str">$1</span>');
    out = out.replace(/\b(def|class|import|from|return|if|else|elif|for|while|in|not|and|or|is|None|True|False|as|with|try|except|raise|pass|break|continue|lambda|yield|self|assert|global|nonlocal)\b/g, '<span class="tok-kw">$1</span>');
    out = out.replace(/\b(\d+\.?\d*)\b/g, '<span class="tok-num">$1</span>');
    out = out.replace(/@(\w+)/g, '<span class="tok-deco">@$1</span>');
    return out;
}

function highlightJs(code) {
    let out = escapeHtml(code);
    out = out.replace(/(\/\/.*)$/gm, '<span class="tok-com">$1</span>');
    out = out.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="tok-com">$1</span>');
    out = out.replace(/(`(?:[^`\\]|\\.)*`|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/g, '<span class="tok-str">$1</span>');
    out = out.replace(/\b(const|let|var|function|return|if|else|for|while|in|of|new|typeof|class|extends|import|export|default|from|require|module|exports|null|undefined|true|false|this|try|catch|throw|switch|case|break|continue)\b/g, '<span class="tok-kw">$1</span>');
    out = out.replace(/\b(\d+\.?\d*)\b/g, '<span class="tok-num">$1</span>');
    return out;
}

function highlightXml(code) {
    // Tokenise le XML brut (pas encore échappé) pour éviter tout risque
    // de double-échappement ou de faux positifs à l'intérieur des
    // commentaires / valeurs d'attributs.
    const re = /(<!--[\s\S]*?-->)|(<\/?[A-Za-z][\w:.-]*)|(\s[A-Za-z_:][\w:.-]*(?=="|='))|("[^"]*"|'[^']*')|(\/?>)/g;
    let result = '';
    let lastIndex = 0;
    let m;
    while ((m = re.exec(code)) !== null) {
        result += escapeHtml(code.slice(lastIndex, m.index));
        if (m[1]) {
            result += `<span class="tok-com">${escapeHtml(m[1])}</span>`;
        } else if (m[2]) {
            result += `<span class="tok-kw">${escapeHtml(m[2])}</span>`;
        } else if (m[3]) {
            const ws = m[3].match(/^\s*/)[0];
            const name = m[3].slice(ws.length);
            result += ws + `<span class="tok-def">${escapeHtml(name)}</span>`;
        } else if (m[4]) {
            result += `<span class="tok-str">${escapeHtml(m[4])}</span>`;
        } else if (m[5]) {
            result += escapeHtml(m[5]);
        }
        lastIndex = re.lastIndex;
    }
    result += escapeHtml(code.slice(lastIndex));
    return result;
}

function renderMarkdown(md) {
    const escaped = escapeHtml(md);
    const lines = escaped.split('\n');
    let html = '';
    let inCode = false, codeBuf = [];
    let inList = false;
    let inTable = false, tableRows = [];

    function flushTable() {
        if (!inTable) return;
        const [headerCells, ...bodyRows] = tableRows;
        html += '<table><thead><tr>' +
            headerCells.map(c => `<th>${inline(c)}</th>`).join('') +
            '</tr></thead><tbody>' +
            bodyRows.map(r => '<tr>' + r.map(c => `<td>${inline(c)}</td>`).join('') + '</tr>').join('') +
            '</tbody></table>';
        inTable = false;
        tableRows = [];
    }

    function parseTableRow(line) {
        // enlève les barres verticales de bord puis découpe sur les barres internes
        const trimmed = line.trim().replace(/^\|/, '').replace(/\|$/, '');
        return trimmed.split('|').map(c => c.trim());
    }

    for (let raw of lines) {
        if (raw.trim().startsWith('```')) {
            flushTable();
            if (!inCode) {
                inCode = true;
                codeBuf = [];
            } else {
                inCode = false;
                html += `<pre><code>${codeBuf.join('\n')}</code></pre>`;
            }
            continue;
        }
        if (inCode) {
            codeBuf.push(raw);
            continue;
        }

        let line = raw;

        // Tables Markdown : ligne d'en-tête "| a | b |" suivie d'une ligne
        // séparatrice "|---|---|"
        const isTableRow = /^\s*\|.*\|\s*$/.test(line);
        const isSeparatorRow = /^\s*\|?[\s:|-]+\|?\s*$/.test(line) && line.includes('-');
        if (isTableRow && !inTable) {
            inTable = true;
            tableRows = [parseTableRow(line)];
            continue;
        }
        if (inTable && isSeparatorRow) {
            continue;
        } // ignore la ligne |---|---|
        if (inTable && isTableRow) {
            tableRows.push(parseTableRow(line));
            continue;
        }
        if (inTable && !isTableRow) {
            flushTable();
        }

        const isListItem = /^\s*[-*]\s+/.test(line);
        if (isListItem && !inList) {
            html += '<ul>';
            inList = true;
        }
        if (!isListItem && inList) {
            html += '</ul>';
            inList = false;
        }

        if (/^### /.test(line)) {
            html += `<h3>${inline(line.replace(/^### /, ''))}</h3>`;
            continue;
        }
        if (/^## /.test(line)) {
            html += `<h2>${inline(line.replace(/^## /, ''))}</h2>`;
            continue;
        }
        if (/^# /.test(line)) {
            html += `<h1>${inline(line.replace(/^# /, ''))}</h1>`;
            continue;
        }
        if (/^&gt; /.test(line)) {
            html += `<blockquote>${inline(line.replace(/^&gt; /, ''))}</blockquote>`;
            continue;
        }
        if (/^\s*---\s*$/.test(line)) {
            html += '<hr>';
            continue;
        }
        if (isListItem) {
            html += `<li>${inline(line.replace(/^\s*[-*]\s+/, ''))}</li>`;
            continue;
        }
        if (line.trim() === '') {
            continue;
        }
        html += `<p>${inline(line)}</p>`;
    }
    flushTable();
    if (inList) html += '</ul>';
    return html;

    function inline(s) {
        s = s.replace(/`([^`]+)`/g, '<code>$1</code>');
        s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
        s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
        return s;
    }
}

const overlay = document.getElementById('modalOverlay');
const tabsEl = document.getElementById('modalTabs');
const bodyEl = document.getElementById('modalBody');
const pathEl = document.getElementById('modalPath');
const copyBtn = document.getElementById('copyBtn');
const downloadBtn = document.getElementById('downloadBtn');
const closeBtn = document.getElementById('closeBtn');

let currentKey = null;
const decodedCache = {};

function getContent(key) {
    if (!decodedCache[key]) decodedCache[key] = decodeB64Utf8(FILES[key].b64);
    return decodedCache[key];
}

function renderTabs() {
    tabsEl.innerHTML = '';
    Object.keys(FILES).forEach(key => {
        const btn = document.createElement('button');
        btn.className = 'modal-tab' + (key === currentKey ? ' active' : '');
        btn.textContent = FILES[key].name;
        btn.addEventListener('click', () => openFile(key));
        tabsEl.appendChild(btn);
    });
}

function openFile(key) {
    currentKey = key;
    const file = FILES[key];
    const content = getContent(key);
    pathEl.textContent = file.path;
    renderTabs();

    if (file.lang === 'markdown') {
        bodyEl.className = 'modal-body markdown';
        bodyEl.innerHTML = renderMarkdown(content);
    } else {
        bodyEl.className = 'modal-body';
        let highlighted = escapeHtml(content);
        if (file.lang === 'python') highlighted = highlightPython(content);
        if (file.lang === 'javascript') highlighted = highlightJs(content);
        if (file.lang === 'xml') highlighted = highlightXml(content);
        bodyEl.innerHTML = `<pre>${highlighted}</pre>`;
    }
    overlay.classList.add('open');
}

function closeModal() {
    overlay.classList.remove('open');
}

document.querySelectorAll('[data-open-file]').forEach(el => {
    el.addEventListener('click', () => openFile(el.getAttribute('data-open-file')));
});

closeBtn.addEventListener('click', closeModal);
overlay.addEventListener('click', (e) => {
    if (e.target === overlay) closeModal();
});
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeModal();
});

copyBtn.addEventListener('click', async () => {
    if (!currentKey) return;
    try {
        await navigator.clipboard.writeText(getContent(currentKey));
        const old = copyBtn.textContent;
        copyBtn.textContent = 'Kopye ✓';
        setTimeout(() => {
            copyBtn.textContent = old;
        }, 1400);
    } catch (e) { /* silencieux */
    }
});

downloadBtn.addEventListener('click', () => {
    if (!currentKey) return;
    const file = FILES[currentKey];
    const blob = new Blob([getContent(currentKey)], {type: 'text/plain;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = file.name;
    a.click();
    URL.revokeObjectURL(url);
});